CREATE TABLE dictionary_definitions (id varchar(64) PRIMARY KEY,dictionary_code varchar(128) NOT NULL,active_dictionary_code varchar(128) GENERATED ALWAYS AS (CASE WHEN deleted_at IS NULL THEN dictionary_code ELSE NULL END) STORED,name text NOT NULL,dictionary_type varchar(16) NOT NULL,source_type varchar(16) NOT NULL,description text NOT NULL,status varchar(16) NOT NULL,extension json NOT NULL,created_at timestamp(6) NOT NULL,created_by text NOT NULL,updated_at timestamp(6) NOT NULL,updated_by text NOT NULL,version bigint NOT NULL,deleted_at timestamp(6) NULL,deleted_by text,UNIQUE KEY dictionary_definitions_code_unique(active_dictionary_code),CHECK(dictionary_type IN('enum','tree')),CHECK(source_type IN('static','provider')),CHECK(status IN('active','disabled')),CHECK(JSON_TYPE(extension)='OBJECT'));
CREATE TABLE dictionary_items (id varchar(64) PRIMARY KEY,dictionary_id varchar(64) NOT NULL,parent_id varchar(64) NULL,code varchar(128) NOT NULL,active_code varchar(128) GENERATED ALWAYS AS (CASE WHEN deleted_at IS NULL THEN code ELSE NULL END) STORED,name text NOT NULL,value text NOT NULL,disabled boolean NOT NULL DEFAULT false,sort_order bigint NOT NULL DEFAULT 0,extension json NOT NULL,created_at timestamp(6) NOT NULL,created_by text NOT NULL,updated_at timestamp(6) NOT NULL,updated_by text NOT NULL,version bigint NOT NULL,deleted_at timestamp(6) NULL,deleted_by text,UNIQUE KEY dictionary_items_id_dictionary_unique(id,dictionary_id),UNIQUE KEY dictionary_items_code_unique(dictionary_id,active_code),KEY dictionary_items_query_idx(dictionary_id,disabled,sort_order),KEY dictionary_items_parent_idx(dictionary_id,parent_id),CONSTRAINT dictionary_items_dictionary_fk FOREIGN KEY(dictionary_id) REFERENCES dictionary_definitions(id),CONSTRAINT dictionary_items_parent_same_dictionary_fk FOREIGN KEY(parent_id,dictionary_id) REFERENCES dictionary_items(id,dictionary_id),CHECK(JSON_TYPE(extension)='OBJECT'));
CREATE TRIGGER dictionary_definitions_audit_bi BEFORE INSERT ON dictionary_definitions FOR EACH ROW SET NEW.created_at=CURRENT_TIMESTAMP(6),NEW.created_by=NULLIF(TRIM(@app_actor_id),''),NEW.updated_at=CURRENT_TIMESTAMP(6),NEW.updated_by=NULLIF(TRIM(@app_actor_id),''),NEW.version=1;
CREATE TRIGGER dictionary_definitions_audit_bu BEFORE UPDATE ON dictionary_definitions FOR EACH ROW SET NEW.created_at=OLD.created_at,NEW.created_by=OLD.created_by,NEW.updated_at=CURRENT_TIMESTAMP(6),NEW.updated_by=NULLIF(TRIM(@app_actor_id),''),NEW.version=OLD.version+1,NEW.deleted_by=CASE WHEN NEW.deleted_at IS NULL THEN NULL WHEN OLD.deleted_at IS NULL THEN NULLIF(TRIM(@app_actor_id),'') ELSE OLD.deleted_by END;
CREATE TRIGGER dictionary_definitions_audit_bd BEFORE DELETE ON dictionary_definitions FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='physical delete is forbidden';
CREATE TRIGGER dictionary_items_audit_bi BEFORE INSERT ON dictionary_items FOR EACH ROW SET NEW.created_at=CURRENT_TIMESTAMP(6),NEW.created_by=NULLIF(TRIM(@app_actor_id),''),NEW.updated_at=CURRENT_TIMESTAMP(6),NEW.updated_by=NULLIF(TRIM(@app_actor_id),''),NEW.version=1;
CREATE TRIGGER dictionary_items_audit_bu BEFORE UPDATE ON dictionary_items FOR EACH ROW SET NEW.created_at=OLD.created_at,NEW.created_by=OLD.created_by,NEW.updated_at=CURRENT_TIMESTAMP(6),NEW.updated_by=NULLIF(TRIM(@app_actor_id),''),NEW.version=OLD.version+1,NEW.deleted_by=CASE WHEN NEW.deleted_at IS NULL THEN NULL WHEN OLD.deleted_at IS NULL THEN NULLIF(TRIM(@app_actor_id),'') ELSE OLD.deleted_by END;
CREATE TRIGGER dictionary_items_audit_bd BEFORE DELETE ON dictionary_items FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='physical delete is forbidden';
